35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "registration_date")
56	    private LocalDate registrationDate;
57	
58	    @Column(name = "birth_date")
59	    private LocalDate birthDate;
60	
61	    @Column(name = "customer_code")
62	    private String customerCode;
63	
64	    @Column(name = "household_id")
65	    private String householdId;
66	
67	    @Column(name = "namesake_count")
68	    private Integer namesakeCount;
69	
70	    @Column(name = "membership_number")
71	    private String membershipNumber;
72	
73	    @Column(name = "bulk_signup_warning")
74	    private Boolean bulkSignupWarning;
75	
76	    @Column(name = "household_size")
77	    private Integer householdSize;
78	
79	    @Column(name = "postcode")
80	    private String postcode;
81	
82	    @Column(name = "possible_duplicate_of")
83	    private Integer possibleDuplicateOf;
84	
85	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
86	    private Set<Pet> pets;
87	
88	    public String getAddress() {
89	        return this.address;
90	    }
91	
92	    public void setAddress(String address) {
93	        this.address = address;
94	    }
95	
96	    public String getCity() {
97	        return this.city;
98	    }
99	
100	    public void setCity(String city) {
101	        this.city = city;
102	    }
103	
104	    public String getTelephone() {
105	        return this.telephone;
106	    }
107	
108	    public void setTelephone(String telephone) {
109	        this.telephone = telephone;
110	    }
111	
112	    /**
113	     * Return this owner's stored E.164 {@link #getTelephone() telephone} formatted for human display
114	     * as the calling code, a space, then the national digits grouped in threes, e.g.
115	     * {@code "+61 412 345 678"}. See {@link TelephoneFormatter}.
116	     */
117	    @Transient
118	    public String getTelephoneDisplay() {
119	        return TelephoneFormatter.toDisplay(this.telephone);
120	    }
121	
122	    public String getEmail() {
123	        return this.email;
124	    }
125	
126	    public void setEmail(String email) {
127	        this.email = email;
128	    }
129	
130	    public LocalDate getRegistrationDate() {
131	        return this.registrationDate;
132	    }
133	
134	    public void setRegistrationDate(LocalDate registrationDate) {
135	        this.registrationDate = registrationDate;
136	    }
137	
138	    public LocalDate getBirthDate() {
139	        return this.birthDate;
140	    }
141	
142	    public void setBirthDate(LocalDate birthDate) {
143	        this.birthDate = birthDate;
144	    }
145	
146	    public String getCustomerCode() {
147	        return this.customerCode;
148	    }
149	
150	    public void setCustomerCode(String customerCode) {
151	        this.customerCode = customerCode;
152	    }
153	
154	    public String getHouseholdId() {
155	        return this.householdId;
156	    }
157	
158	    public void setHouseholdId(String householdId) {
159	        this.householdId = householdId;
160	    }
161	
162	    public Integer getNamesakeCount() {
163	        return this.namesakeCount;
164	    }
165	
166	    public void setNamesakeCount(Integer namesakeCount) {
167	        this.namesakeCount = namesakeCount;
168	    }
169	
170	    public String getMembershipNumber() {
171	        return this.membershipNumber;
172	    }
173	
174	    public void setMembershipNumber(String membershipNumber) {
175	        this.membershipNumber = membershipNumber;
176	    }
177	
178	    /**
179	     * Whether this owner was created after more than 80 owners had already been registered on the
180	     * same day, flagging an unusually high-volume ("bulk") signup. Captured once at creation.
181	     */
182	    public Boolean getBulkSignupWarning() {
183	        return this.bulkSignupWarning;
184	    }
185	
186	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
187	        this.bulkSignupWarning = bulkSignupWarning;
188	    }
189	
190	    /**
191	     * The number of owners in this owner's household (owners sharing the same {@code householdId},
192	     * counting this owner) captured once at creation.
193	     */
194	    public Integer getHouseholdSize() {
195	        return this.householdSize;
196	    }
197	
198	    public void setHouseholdSize(Integer householdSize) {
199	        this.householdSize = householdSize;
200	    }
201	
202	    /**
203	     * This owner's 4-digit postcode, or {@code null} when none was supplied. When present it is
204	     * validated against the owner's city region at creation (see {@code PostcodeValidator}).
205	     */
206	    public String getPostcode() {
207	        return this.postcode;
208	    }
209	
210	    public void setPostcode(String postcode) {
211	        this.postcode = postcode;
212	    }
213	
214	    /**
215	     * The id of an existing owner this owner was flagged as a possible (soft) duplicate of at
216	     * creation, or {@code null} when none. Because owners sharing a last name and postcode now form
217	     * the same household — rejected as a household duplicate unless declared via {@code sharesHousehold},
218	     * and a declared member is not a suspected duplicate — this is not populated at creation.
219	     * Captured once at creation.
220	     */
221	    public Integer getPossibleDuplicateOf() {
222	        return this.possibleDuplicateOf;
223	    }
224	
225	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
226	        this.possibleDuplicateOf = possibleDuplicateOf;
227	    }
228	
229	    /**
230	     * Whether this owner was flagged as a possible (soft) duplicate of an existing owner at creation,
231	     * i.e. whether {@link #getPossibleDuplicateOf()} is set.
232	     */
233	    @Transient
234	    public Boolean getPossibleDuplicate() {
235	        return this.possibleDuplicateOf != null;
236	    }
237	
238	    /**
239	     * Return this owner's name formatted for display as {@code "LastName, FirstName"}.
240	     */
241	    @Transient
242	    public String getDisplayName() {
243	        return this.getLastName() + ", " + this.getFirstName();
244	    }
245	
246	    /**
247	     * Return this owner's initials as the upper-cased first letters of the first and last
248	     * name, dot-separated with a trailing dot, e.g. {@code "J.S."}.
249	     */
250	    @Transient
251	    public String getInitials() {
252	        return initial(this.getFirstName()) + initial(this.getLastName());
253	    }
254	
255	    private static String initial(String name) {
256	        return Character.toUpperCase(name.charAt(0)) + ".";
257	    }
258	
259	    /** The membership level every owner starts at on creation. */
260	    private static final int BASE_MEMBERSHIP_LEVEL = 1;
261	
262	    /** The highest membership level attainable; only reached with qualifying tenure. */
263	    private static final int MAX_MEMBERSHIP_LEVEL = 4;
264	
265	    /** The tenure, in days, that must be exceeded to qualify for the top membership level. */
266	    private static final long MEMBERSHIP_TENURE_THRESHOLD_DAYS = 365;
267	
268	    /**
269	     * Return this owner's membership level, a number from 1 to 4: every owner starts at
270	     * {@value #BASE_MEMBERSHIP_LEVEL}; add 1 when an email address is present; add 1 when the owner
271	     * has no namesakes ({@code namesakeCount} is 0); add 1 when the owner has qualifying tenure
272	     * (more than {@value #MEMBERSHIP_TENURE_THRESHOLD_DAYS} days since registration); capped at
273	     * {@value #MAX_MEMBERSHIP_LEVEL}. Because a newly created owner has zero tenure, a new owner
274	     * never exceeds level 3.
275	     */
276	    @Transient
277	    public Integer getMembershipLevel() {
278	        int level = BASE_MEMBERSHIP_LEVEL;
279	        if (hasEmail()) {
280	            level++;
281	        }
282	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
283	            level++;
284	        }
285	        if (hasQualifyingTenure()) {
286	            level++;
287	        }
288	        return Math.min(level, MAX_MEMBERSHIP_LEVEL);
289	    }
290	
291	    /**
292	     * Whether this owner's tenure exceeds {@value #MEMBERSHIP_TENURE_THRESHOLD_DAYS} days, i.e.
293	     * more than that many days have elapsed since the {@code registrationDate}. Owners without a
294	     * registration date have no measurable tenure and do not qualify.
295	     */
296	    private boolean hasQualifyingTenure() {
297	        if (this.registrationDate == null) {
298	            return false;
299	        }
300	        long tenureDays = ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
301	        return tenureDays > MEMBERSHIP_TENURE_THRESHOLD_DAYS;
302	    }
303	
304	    /** Whether this owner has a usable email address (present and not blank). */
305	    private boolean hasEmail() {
306	        return this.email != null && !this.email.isBlank();
307	    }
308	
309	    /**
310	     * Return this owner's preferred contact channel: {@code "EMAIL"} when an email address is
311	     * present, otherwise {@code "PHONE"}.
312	     */
313	    @Transient
314	    public String getContactPreference() {
315	        return hasEmail() ? "EMAIL" : "PHONE";
316	    }
317	
318	    /**
319	     * Return this owner's age band derived from the {@code birthDate} as of the
320	     * {@code registrationDate}, or {@code null} when no birth date is known.
321	     */
322	    @Transient
323	    public AgeBand getAgeBand() {
324	        if (this.birthDate == null || this.registrationDate == null) {
325	            return null;
326	        }
327	        return AgeBand.asOf(this.birthDate, this.registrationDate);
328	    }
329	
330	    /**
331	     * Return this owner's locality: the region segment of the {@code customerCode} (the leading
332	     * {@code <REGION>} of {@code <REGION>-<HASH8>}), which is fixed at creation from the postcode
333	     * (preferred, matched against the known region ranges) falling back to the city-to-region table,
334	     * or {@code "UNKNOWN"} when neither yields a region. Before the customer code is assigned the
335	     * region is resolved directly from the postcode and city.
336	     */
337	    @Transient
338	    public String getLocality() {
339	        if (this.customerCode == null) {
340	            return LocalityResolver.regionFor(this.postcode, this.city);
341	        }
342	        int separator = this.customerCode.indexOf('-');
343	        return separator < 0 ? this.customerCode : this.customerCode.substring(0, separator);
344	    }
345	
346	    /**
347	     * Return this owner's check digit: the single Luhn check digit computed over the digits of the
348	     * {@code customerCode}.
349	     */
350	    @Transient
351	    public Integer getCheckDigit() {
352	        return this.customerCode == null ? null : LuhnCheckDigit.of(this.customerCode);
353	    }
354	
355	    /**
356	     * Return this owner's identity key, the single derived value all duplicate detection is based
357	     * on: the normalized telephone, email and household id joined with {@code '|'} as
358	     * {@code telephone + "|" + email + "|" + householdId}, with each absent component rendered as
359	     * the empty string. Two owners are duplicates only when their whole identity keys are equal;
360	     * because the telephone is part of the key, members of one household (same {@code householdId})
361	     * with different telephones have distinct keys and are not duplicates.
362	     */
363	    @Transient
364	    public String getIdentityKey() {
365	        return keyPart(this.telephone) + "|" + keyPart(this.email) + "|" + keyPart(this.householdId);
366	    }
367	
368	    private static String keyPart(String value) {
369	        return value == null ? "" : value;
370	    }
371	
372	    protected Set<Pet> getPetsInternal() {
373	        if (this.pets == null) {
374	            this.pets = new HashSet<>();
375	        }
376	        return this.pets;
377	    }
378	
379	    protected void setPetsInternal(Set<Pet> pets) {
380	        this.pets = pets;
381	    }
382	
383	    public List<Pet> getPets() {
384	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
385	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
386	        return Collections.unmodifiableList(sortedPets);
387	    }
388	
389	    public void setPets(List<Pet> pets) {
390	        this.pets = new HashSet<>(pets);
391	    }
392	
393	    public void addPet(Pet pet) {
394	        getPetsInternal().add(pet);
395	        pet.setOwner(this);
396	    }
397	
398	    /**
399	     * Return the Pet with the given name, or null if none found for this Owner.
400	     *
401	     * @param name to test
402	     * @return true if pet name is already in use
403	     */
404	    public Pet getPet(String name) {
405	        return getPet(name, false);
406	    }
407	
408	    /**
409	     * Return the Pet with the given name, or null if none found for this Owner.
410	     *
411	     * @param name to test
412	     * @return true if pet name is already in use
413	     */
414	    public Pet getPet(String name, boolean ignoreNew) {
415	        name = name.toLowerCase();
416	        for (Pet pet : getPetsInternal()) {
417	            if (!ignoreNew || !pet.isNew()) {
418	                String compName = pet.getName();
419	                compName = compName.toLowerCase();
420	                if (compName.equals(name)) {
421	                    return pet;
422	                }
423	            }
424	        }
425	        return null;
426	    }
427	
428	    public Pet getPet(Integer petId) {
429	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
430	    }
431	
432	    @Override
433	    public String toString() {
434	        return new ToStringCreator(this)
435	
436	            .append("id", this.getId())
437	            .append("new", this.isNew())
438	            .append("lastName", this.getLastName())
439	            .append("firstName", this.getFirstName())
440	            .append("address", this.address)
441	            .append("city", this.city)
442	            .append("telephone", this.telephone)
443	            .append("email", this.email)
444	            .append("registrationDate", this.registrationDate)
445	            .toString();
446	    }
447	}
